 using System.ComponentModel;
 using System.Net.Http.Json;
 using Microsoft.Extensions.Logging;
 using ModelContextProtocol.Server;

 /// <summary>
 /// MCP tools that wrap a JSONPlaceholder REST API.
 /// Uses constructor injection — HttpClient and ILogger are resolved via DI.
 /// </summary>
 [McpServerToolType]
 public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
 {
     [McpServerTool, Description("Get a user profile by ID from the REST API.")]
     public async Task<string> GetUser(
         [Description("The user ID (1-10).")] int userId,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Fetching user {UserId}", userId);
         var json = await httpClient.GetStringAsync($"users/{userId}", cancellationToken);
         return json;
     }

     [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
     public async Task<string> ListPosts(
         [Description("Filter posts to this user ID. Omit to list all.")] int? userId = null,
         CancellationToken cancellationToken = default)
     {
         var url = userId.HasValue ? $"posts?userId={userId}" : "posts";
         logger.LogInformation("Listing posts: {Url}", url);
         var json = await httpClient.GetStringAsync(url, cancellationToken);
         return json;
     }

     [McpServerTool, Description("Create a new post via the REST API.")]
     public async Task<string> CreatePost(
         [Description("The user ID authoring the post.")] int userId,
         [Description("The post title.")] string title,
         [Description("The post body text.")] string body,
         CancellationToken cancellationToken = default)
     {
         var payload = new { userId, title, body };
         logger.LogInformation("Creating post for user {UserId}", userId);

         var response = await httpClient.PostAsJsonAsync("posts", payload, cancellationToken);
         response.EnsureSuccessStatusCode();

         var result = await response.Content.ReadAsStringAsync(cancellationToken);
         return result;
     }
 }
